const i = $input.first().json;

const prompt = `Please summarize this content.

Source: ${i.source_type || 'unknown'}
Title: ${i.title || ''}
${i.author_or_source ? 'Author/Channel: ' + i.author_or_source + '\n' : ''}
${i.source_url ? 'URL: ' + i.source_url + '\n' : ''}

Content:
${i.raw_content || ''}

IMPORTANT: Write the summary in the SAME LANGUAGE as the content. Do not translate to English.

Provide a concise summary. Format your response exactly as follows:

**TLDR**
[Single paragraph, 3-4 sentences capturing the main idea]

**Summary**
[Detailed 3-5 paragraph summary capturing key points, arguments, and conclusions]

**Tags**
[3-5 short topic tags on a single line, comma-separated, lowercase, hyphenated for multi-word tags. Examples: ai-safety, llm-evaluation, product-strategy, government-policy. Tags MUST always be in English (translate from the source language if needed) so the tag set stays uniform across items.]

Write the TLDR and Summary in clear, informative prose. No bullet points.
`;

return [{ json: { ...i, _gemini_prompt: prompt } }];

const input = $('When called by another workflow').first().json;
const llm = $input.first().json;

// Multiple LLM response shapes covered:
//   * Gemini direct REST (current)        — candidates[0].content.parts[0].text
//   * Legacy googleGemini langchain node  — content.parts[0].text
//   * OpenAI / s07 FastAPI shape          — choices[0].message.content
const summaryRaw =
  llm?.candidates?.[0]?.content?.parts?.[0]?.text ??
  llm?.choices?.[0]?.message?.content ??
  llm?.message?.content ??
  llm?.content?.parts?.[0]?.text;
if (!summaryRaw) { throw new Error('MISSING: LLM returned no summary text'); }

let summary = summaryRaw;
let tags = [];
const tagMatch = summary.match(/\*\*Tags\*\*\s*\n([\s\S]*?)\s*$/);
if (tagMatch) {
  const line = tagMatch[1].split('\n')[0];
  tags = line
    .split(/[,;]/)
    .map(s => s.trim().toLowerCase().replace(/^[#\-\s]+|[\.\s]+$/g, '').replace(/\s+/g, '-'))
    .filter(s => s && s.length <= 40)
    .slice(0, 5);
  summary = summary.slice(0, tagMatch.index).replace(/\s+$/, '');
}

return [{
  json: {
    source_type:      input.source_type,
    external_id:      input.external_id,
    source_url:       input.source_url || null,
    title:            input.title,
    author_or_source: input.author_or_source || null,
    published_at:     input.published_at || null,
    raw_content:      input.raw_content || null,
    content_md:       input.content_md || '',
    ai_summary:       summary,
    tags:             tags,
    thumbnail_url:    input.thumbnail_url || null,
    source_metadata:  input.source_metadata || {},
    shared_at:        input.shared_at || null
  }
}];

const row = $('Compose Inbox Row').first().json;
return [{
  json: {
    video_id:       row.external_id + '-' + Date.now(),
    process_status: 'success',
    error_type:     null,
    notes:          `[${row.source_type}] ${row.title}`
  }
}];

const row = $('Compose Inbox Row').first().json;
const input = $('When called by another workflow').first().json;

const summary = row.ai_summary || 'No summary available';
const safeLimit = 1900;
const chunks = [];

let header = `Saved! **${row.title}**`;
if (row.author_or_source) header += ` by **${row.author_or_source}**`;
if (row.source_type === 'youtube' && input.source_metadata) {
  const sm = input.source_metadata;
  if (sm.duration) {
    header += ` | ${Math.floor(sm.duration / 60)}m ${sm.duration % 60}s`;
  }
  if (sm.view_count) header += ` | ${sm.view_count} views`;
}
header += ` ---\n\n`;

let remaining = summary;
while (remaining.length > 0) {
  const isFirst = chunks.length === 0;
  const max = isFirst ? safeLimit - header.length : safeLimit;
  if (remaining.length <= max) {
    chunks.push({ json: { chunk: (isFirst ? header : '') + remaining, channel_id: input.discord_channel_id } });
    break;
  }
  let split = remaining.lastIndexOf(' ', max);
  if (split === -1) split = max;
  let text = remaining.substring(0, split);
  if (isFirst) text = header + text;
  chunks.push({ json: { chunk: text, channel_id: input.discord_channel_id } });
  remaining = remaining.substring(split).trim();
}
return chunks;
